questionvariables.text:
shapes:random_permutation(["trapezium", "parallelogram"]);
shapeA:first(shapes);
shapeB:second(shapes);

/* Trapezium */
trapA:rand(4)+3;
trapB:rand_with_step(trapA+1,9,1);
trapH:rand(4)+3;

trapArea:trapH*(trapA+trapB)/2
trapPer:trapA+trapB+2*sqrt(trapH^2 + (trapB-trapA)^2/4);

/* Parallelogram */
paraB:rand(4)+3;
paraL:rand_with_step(1,8-paraB,1);
paraH:rand(4)+3;

paraArea:paraB*paraH;
paraPer:2*paraB+2*sqrt(paraL^2+paraH^2);

/* Solutions */

tans1: if shapeA="trapezium" then trapArea else if shapeA="parallelogram" then paraArea;
tans2: if shapeA="trapezium" then trapPer else if shapeA="parallelogram" then paraPer;

tans3: if shapeB="trapezium" then trapA else if shapeB="parallelogram" then paraB;
tans4: if shapeB="trapezium" then trapB else if shapeB="parallelogram" then paraL;

